<div class="wrap"><h1>Sectores</h1><?php if($message):?><div class="notice notice-info"><p><?=esc_html($message)?></p></div><?php endif;?><?php $forms=array_merge([['id'=>0,'name'=>'','commune'=>'','status'=>'active','store_ids'=>'']],$zones);foreach($forms as $z):$assigned=array_filter(array_map('intval',explode(',',(string)($z['store_ids']??''))));?><form method="post" style="background:#fff;border:1px solid #ccd0d4;padding:16px;margin:16px 0"><?php wp_nonce_field('va_sectors');?><input type="hidden" name="id" value="<?=absint($z['id'])?>"><h2><?= $z['id']?'Editar '.esc_html($z['name']):'Crear sector' ?></h2><table class="form-table"><tr><th>Sector</th><td><input required name="name" value="<?=esc_attr($z['name'])?>"></td></tr><tr><th>Comuna</th><td><input required name="commune" value="<?=esc_attr($z['commune'])?>"></td></tr><tr><th>Estado</th><td><select name="status"><option value="active" <?=selected($z['status'],'active',false)?>>Activo</option><option value="inactive" <?=selected($z['status'],'inactive',false)?>>Inactivo</option></select></td></tr><tr><th>Minimarkets asignados</th><td><?php foreach($stores as $s):?><label style="display:block"><input type="checkbox" name="stores[]" value="<?=absint($s['id'])?>" <?=checked(in_array((int)$s['id'],$assigned,true),true,false)?>> <?=esc_html($s['business_name'])?> (<?=esc_html($s['status'])?>)</label><?php endforeach;?></td></tr></table><?php submit_button($z['id']?'Guardar cambios':'Crear sector');?></form><?php endforeach;?></div>
